package com.sponsormatch.exception;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.Map;
@RestControllerAdvice public class ApiExceptionHandler { record ErrorResponse(Instant timestamp,int status,String message){} @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e){return ResponseEntity.status(e.status()).body(new ErrorResponse(Instant.now(),e.status().value(),e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) ErrorResponse validation(MethodArgumentNotValidException e){return new ErrorResponse(Instant.now(),400,e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Validation failed"));} @ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) ErrorResponse unexpected(Exception e){return new ErrorResponse(Instant.now(),500,"An unexpected error occurred.");} }
